import {languagePriorities} from './learning-plan.mjs';
import {whyStories} from './why.mjs';
import {esc,link} from './academy-views.mjs';
export function whyView(data,focus){
 const language=data.languages.find(l=>l.id===focus)||data.languages[0],story=whyStories[language.id];
 const sourceLink=(i,label='Read the history ↗')=>i===null?'':`<a class="a-text-link" href="${esc(story.sources[i][1])}" target="_blank" rel="noopener noreferrer">${label}</a>`;
 const project=data.projects.find(p=>p.id===story.project)||data.projects.find(p=>p.language===language.id);
 return `<div class="a-heading"><div><p class="overline">THE HISTORY. THE PURPOSE. YOUR REASON.</p><h1>Know why<br><em>you’re learning it.</em></h1><p>Each language grew out of a real problem. Understand that problem, and its place in your aerospace journey becomes much clearer.</p></div></div>
 <nav class="why-language-nav" aria-label="Choose a language to understand">${data.languages.map(l=>`<a href="#why?lang=${l.id}" ${l.id===language.id?'aria-current="page"':''}><span class="language-chip" style="--chip:${l.color}">${esc(l.symbol)}</span><span><b>${l.name}</b><small>${whyStories[l.id].role}</small></span></a>`).join('')}</nav>
 <section class="why-hero"><div><span class="overline">WHY ${esc(language.name).toUpperCase()}</span><h2>${esc(story.tagline)}</h2><p>${esc(story.meaning)}</p><div class="why-origin"><span>${esc(story.origin)}</span><b>${esc(story.era)}</b></div></div><span class="why-emblem" style="--why-accent:${language.color}" aria-hidden="true">${esc(language.symbol)}</span></section>
 <div class="why-history-grid"><section><div class="panel-heading"><h2>Where it came from.</h2><span>HISTORY</span></div><p class="why-history-intro">${esc(story.born)}</p><div class="why-source-note">${story.sources.map((_,i)=>sourceLink(i,`${esc(story.sources[i][0])} ↗`)).join('')}</div><ol class="why-timeline">${story.timeline.map(([date,title,body,source])=>`<li><span>${date}</span><div><h3>${esc(title)}</h3><p>${esc(body)}</p>${sourceLink(source)}</div></li>`).join('')}</ol></section><aside class="why-carry"><span class="overline">WHAT STAYS WITH YOU</span><h2>The durable skill is bigger than the syntax.</h2><p>${esc(story.carry)}</p><div><span class="overline">YOUR LEARNING PRIORITY</span><p>${esc(languagePriorities[language.id])}. ${esc(story.timing)}</p><a class="a-text-link" href="#focus">See the readiness checkpoints →</a></div><div><span class="overline">A USEFUL PROOF OF PROGRESS</span><p>${esc(story.proof)}</p></div>${link('Start the first lesson ↗','#lesson/'+story.lesson)}</aside></div>
 <div class="panel-heading section-spacer"><h2>Why it deserves your time.</h2><span>YOUR AEROSPACE PATH</span></div><div class="why-value-grid">${story.value.map(([title,body],i)=>`<article class="a-panel"><span class="overline">0${i+1}</span><h3>${esc(title)}</h3><p>${esc(body)}</p></article>`).join('')}</div>
 <section class="why-scenario section-spacer"><div><span class="overline">ONE CONCRETE REASON TO PRACTICE</span><h2>${esc(story.example.title)}</h2><p>${esc(story.example.before)}</p><ol class="step-list">${story.example.work.map((s,i)=>`<li><b>0${i+1}</b><p>${esc(s)}</p></li>`).join('')}</ol></div><div class="why-outcome"><span class="overline">WHAT THE SKILL CHANGES</span><p>${esc(story.example.after)}</p>${project?link('Build a related project ↗','#project/'+project.id):''}</div></section>
 <section class="a-panel section-spacer"><span class="overline">THE HONEST COST OF LEARNING IT</span><h2>Worthwhile does not mean effortless.</h2><p>${esc(story.tradeoff)}</p><div class="a-actions">${link('Explore the '+esc(language.name)+' curriculum','#library?lang='+language.id+'&kind=lesson')}${link('Books, courses & references','#library?lang='+language.id+'&kind=resource','a-button subtle')}</div></section>
 <section class="why-together section-spacer"><span class="overline">WHY ALL FIVE?</span><h2>Different layers of the same engineering work.</h2><p>On an illustrative rover project, Python can investigate the data, MATLAB can explore a mathematical model, C++ can organize software components, C can clarify an embedded interface, and Bash can make the workflow repeatable. A real project may use only some of these. You do not need to master them all before building anything.</p><p><b>Your sequence:</b> Python first with one CAD package; a little Bash from the start. Add C++ after comfortable Python fundamentals. MATLAB follows coursework and may come earlier; C follows an embedded project. Expert mastery is not required before the next tool.</p><p class="a-small">Return here when the exercises feel abstract. Pick one problem you want to solve, then use the linked lesson or project to take the next step.</p></section>`;
}
